const toko = 'Kopi Rina';
const pesanan = [
  { nama: 'Kopi Susu', harga: 18000, jumlah: 2 },
  { nama: 'Roti Bakar', harga: 15000, jumlah: 1 },
];
console.log('=== ' + toko + ' ===');
for (const p of pesanan) console.log(`${p.nama} x${p.jumlah}`);
const total = pesanan.reduce((a, p) => a + p.harga * p.jumlah, 0);
